```python
def spread_chars(s):
    from collections import Counter
    if not s:
        return ''
    counts = Counter(s)
    heap = [(-c, ch) for ch, c in counts.items()]
    import heapq
    heapq.heapify(heap)
    out = []
    while heap:
        neg, ch = heapq.heappop(heap)
        if out and out[-1] == ch:
            if not heap:
                return ''
            neg2, ch2 = heapq.heappop(heap)
            out.append(ch2)
            if neg2 + 1:
                heapq.heappush(heap, (neg2 + 1, ch2))
            heapq.heappush(heap, (neg, ch))
        else:
            out.append(ch)
            if neg + 1:
                heapq.heappush(heap, (neg + 1, ch))
    return ''.join(out)
```

